import 'dart:convert';\nimport 'dart:io';\nimport 'package:path/path.dart' as path;\n\nimport 'src/json_processor.dart';\nimport 'src/csv_exporter.dart';\nimport 'src/text_sanitizer.dart';\nimport 'src/statistics_calculator.dart';\n\nvoid main() async {\n  final jsonProcessor = JsonProcessor();\n  final csvExporter = CsvExporter();\n  final textSanitizer = TextSanitizer();\n  final statsCalculator = StatisticsCalculator();\n\n  print('=== Data Processing Utilities Demo ===\\n');\n\n  // 1. JSON Processing\n  print('--- JSON Processing ---');\n  final sampleJson = '''\n  {\n    \"users\": [\n      {\"id\": 1, \"name\": \"Alice\", \"active\": true},\n      {\"id\": 2, \"name\": \"Bob\", \"active\": false},\n      {\"id\": 3, \"name\": \"Charlie\", \"active\": true}\n    ]\n  }\n  ''';\n\n  final parsedData = jsonProcessor.parseJson(sampleJson);\n  if (parsedData != null) {\n    print('Parsed successfully. Top-level keys: \\${parsedData.keys.toList()}');\n    final users = parsedData['users'] as List<dynamic>;\n    print('Number of users: \\${users.length}');\n    \n    // Validate specific field\n    final isValid = jsonProcessor.validateField(users[0], 'name', 'string');\n    print('User[0].name is valid string: \\$isValid');\n    \n    // Transform data (e.g., filter active users)\n    final activeUsers = jsonProcessor.transform(users, (user) {\n      return (user['active'] == true) ? user : null;\n    });\n    print('Active users count: \\${activeUsers.length}');\n    \n    // Save to file\n    final outputPath = path.join(Directory.current.path, 'output', 'processed_users.json');\n    await jsonProcessor.saveToJson(activeUsers, outputPath);\n    print('Saved active users to: \\$outputPath\\n');\n  } else {\n    print('JSON parsing failed.\\n');\n  }\n\n  // 2. CSV Export\n  print('--- CSV Export ---');\n  final csvData = [\n    {'id': 1, 'name': 'Alice', 'score': 95.5},\n    {'id': 2, 'name': 'Bob', 'score': 87.2},\n    {'id': 3, 'name': 'Charlie', 'score': 92.0},\n  ];\n  \n  final csvPath = path.join(Directory.current.path, 'output', 'scores.csv');\n  await csvExporter.exportToCsv(csvData, csvPath);\n  print('Exported CSV to: \\${path.basename(csvPath)}');\n  print('Content preview:');\n  print(File(csvPath).readAsStringSync());\n  print('');\n\n  // 3. Text Sanitization\n  print('--- Text Sanitization ---');\n  final rawText = '\\t  Hello   World  !!!  😀 🚀  Special chars: @#\$%^&*()  \\n  Extra whitespace    \\n  ';\n  \n  print('Original: [\\$rawText]');\n  \n  final sanitized = textSanitizer.sanitizeText(rawText);\n  print('Sanitized (whitespace/emoji/special): [\\$sanitized]');\n  \n  final lowerCased = textSanitizer.normalizeCase(sanitized);\n  print('Lowercased: [\\$lowerCased]');\n  \n  final maxLength = textSanitizer.truncateText(sanitized, 20);\n  print('Truncated (20 chars): [\\$maxLength]\\n');\n\n  // 4. Statistics Calculation\n  print('--- Statistics Calculation ---');\n  final numbers = [10.0, 15.0, 20.0, 10.0, 25.0, 30.0, 10.0, 35.0];\n  \n  final mean = statsCalculator.calculateMean(numbers);\n  final median = statsCalculator.calculateMedian(numbers);\n  final mode = statsCalculator.calculateMode(numbers);\n  final variance = statsCalculator.calculateVariance(numbers);\n  final stdDev = statsCalculator.calculateStandardDeviation(numbers);\n  \n  print('Data: \\${numbers.join(', ')}');\n  print('Mean: \\${mean.toStringAsFixed(2)}');\n  print('Median: \\${median.toStringAsFixed(2)}');\n  print('Mode: \\${mode}');\n  print('Variance: \\${variance.toStringAsFixed(2)}');\n  print('Standard Deviation: \\${stdDev.toStringAsFixed(2)}');\n  \n  // Outlier detection (simple z-score > 2)\n  final outliers = statsCalculator.detectOutliers(numbers);\n  print('Outliers (|z| > 2): \\${outliers.map((o) => o[0]).toList()}\\n');\n\n  print('=== Processing Complete ===');\n  \n  // Cleanup demo output files\n  File(csvPath).deleteSync();\n  if (File(outputPath).existsSync()) {\n    File(outputPath).deleteSync();\n  }\n}\n
